package com.atmaca.kasa100;
import android.app.*;import android.content.*;import android.database.*;import android.database.sqlite.*;import android.os.*;import java.io.*;import java.util.*;import java.security.*;
public class VaultService extends Service {
static volatile boolean cancel=false;static volatile boolean busy=false;SQLiteDatabase db;File vault;int done,errors;NotificationManager nm;
static SQLiteDatabase open(Context c){SQLiteDatabase d=c.openOrCreateDatabase("vault.db",0,null);d.execSQL("CREATE TABLE IF NOT EXISTS photos(id INTEGER PRIMARY KEY AUTOINCREMENT,src TEXT UNIQUE,name TEXT,stored TEXT,size INTEGER,hash TEXT,state INTEGER DEFAULT 0,out TEXT)");d.execSQL("CREATE TABLE IF NOT EXISTS released(path TEXT PRIMARY KEY,size INTEGER,stamp INTEGER)");d.execSQL("CREATE INDEX IF NOT EXISTS photo_state ON photos(state,id)");return d;}
static long count(Context c){try(SQLiteDatabase d=open(c);Cursor q=d.rawQuery("SELECT COUNT(*) FROM photos WHERE state IN (1,2)",null)){q.moveToFirst();return q.getLong(0);}catch(Exception e){return 0;}}
public IBinder onBind(Intent i){return null;}
public int onStartCommand(Intent i,int f,int id){if(busy)return START_NOT_STICKY;if(i==null){stopSelf();return START_NOT_STICKY;}busy=true;cancel=false;nm=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);nm.createNotificationChannel(new NotificationChannel("work","Fotoğraf taşıma",NotificationManager.IMPORTANCE_LOW));startForeground(100,notification("Başlıyor"));String op=i.getStringExtra("op"),out=i.getStringExtra("out");new Thread(()->{try{db=open(this);vault=new File(getFilesDir(),"photos");if(!vault.exists()&&!vault.mkdirs())throw new IOException("Kasa açılamadı");recover();if("import".equals(op))collect(new File(out));else export(new File(out),"remainder".equals(op));}catch(Exception e){status("Hata: "+e.getMessage());}finally{if(db!=null)db.close();busy=false;stopForeground(true);stopSelf();}},"vault-worker").start();return START_NOT_STICKY;}
Notification notification(String s){return new Notification.Builder(this,"work").setContentTitle("ATMACA KASA 100").setContentText(s).setSmallIcon(android.R.drawable.ic_menu_gallery).build();}
void status(String s){getSharedPreferences("state",0).edit().putString("status",s).apply();if(Build.VERSION.SDK_INT<33 || checkSelfPermission("android.permission.POST_NOTIFICATIONS")==android.content.pm.PackageManager.PERMISSION_GRANTED)nm.notify(100,notification(s));}
String hash(File f)throws Exception{MessageDigest m=MessageDigest.getInstance("SHA-256");byte[] b=new byte[262144];try(InputStream in=new FileInputStream(f)){int n;while((n=in.read(b))!=-1)m.update(b,0,n);}StringBuilder s=new StringBuilder();for(byte v:m.digest())s.append(String.format("%02x",v));return s.toString();}
void copy(File a,File b)throws Exception{try(FileInputStream in=new FileInputStream(a);FileOutputStream out=new FileOutputStream(b)){byte[] buf=new byte[262144];int n;while((n=in.read(buf))!=-1)out.write(buf,0,n);out.getFD().sync();}}
void recover()throws Exception{try(Cursor c=db.rawQuery("SELECT id,src,stored,size,hash,state,out FROM photos WHERE state IN (0,2)",null)){while(c.moveToNext()){long id=c.getLong(0);File src=new File(c.getString(1)),stored=new File(c.getString(2));int state=c.getInt(5);if(state==0){if(stored.exists()&&stored.length()==c.getLong(3)&&hash(stored).equals(c.getString(4))){if(!src.exists()||(src.length()==c.getLong(3)&&hash(src).equals(c.getString(4))&&src.delete()))db.execSQL("UPDATE photos SET state=1 WHERE id=?",new Object[]{id});}else if(src.exists()){stored.delete();db.delete("photos","id=?",new String[]{""+id});}}else{File out=new File(c.getString(6));if(out.exists()&&out.length()==c.getLong(3)&&hash(out).equals(c.getString(4))){released(out);if(!stored.exists()||stored.delete())db.delete("photos","id=?",new String[]{""+id});}else{db.execSQL("UPDATE photos SET state=1,out=NULL WHERE id=?",new Object[]{id});}}}}}
void released(File f){db.execSQL("INSERT OR REPLACE INTO released VALUES(?,?,?)",new Object[]{f.getAbsolutePath(),f.length(),f.lastModified()});}
boolean isReleased(File f){try(Cursor q=db.rawQuery("SELECT size,stamp FROM released WHERE path=?",new String[]{f.getAbsolutePath()})){return q.moveToFirst()&&q.getLong(0)==f.length()&&q.getLong(1)==f.lastModified();}}
boolean image(File f){String n=f.getName().toLowerCase(Locale.ROOT);return n.matches(".*\\.(jpg|jpeg|png|webp|gif|bmp|heic|heif|avif|dng|tif|tiff)$");}
void collect(File output)throws Exception{done=errors=0;ArrayDeque<File> dirs=new ArrayDeque<>();Set<String> roots=new HashSet<>();roots.add(Environment.getExternalStorageDirectory().getCanonicalPath());File[] ex=getExternalFilesDirs(null);for(File f:ex)if(f!=null){String p=f.getCanonicalPath();int n=p.indexOf("/Android/");if(n>0)roots.add(p.substring(0,n));}for(String p:roots)dirs.add(new File(p));String exclude=output.getCanonicalPath();status("Klasörler taranıyor...");while(!dirs.isEmpty()&&!cancel){File dir=dirs.removeLast();File[] fs=dir.listFiles();if(fs==null){errors++;continue;}for(File f:fs){if(cancel)break;String p=f.getCanonicalPath();if(p.equals(exclude)||p.startsWith(exclude+"/"))continue;if(f.isDirectory()){if(p.endsWith("/Android/data")||p.endsWith("/Android/obb"))continue;dirs.add(f);}else if(image(f)&&!isReleased(f)){try{importOne(f);}catch(Exception e){errors++;}if((done+errors)%20==0)status("Kasaya taşınan: "+done+" | Atlanan/hata: "+errors);}}}status((cancel?"Durduruldu. ":"Tamamlandı. ")+"Taşınan: "+done+" | Atlanan/hata: "+errors);}
void importOne(File src)throws Exception{try(Cursor q=db.rawQuery("SELECT id FROM photos WHERE src=?",new String[]{src.getAbsolutePath()})){if(q.moveToFirst())return;}long size=src.length(),stamp=src.lastModified();if(size<=0)return;String h=hash(src);File dst=new File(vault,UUID.randomUUID().toString());File tmp=new File(dst+".part");try{copy(src,tmp);if(src.length()!=size||src.lastModified()!=stamp||tmp.length()!=size||!hash(tmp).equals(h))throw new IOException("Doğrulama başarısız");if(!tmp.renameTo(dst))throw new IOException("Kaydetme başarısız");ContentValues v=new ContentValues();v.put("src",src.getAbsolutePath());v.put("name",src.getName());v.put("stored",dst.getAbsolutePath());v.put("size",size);v.put("hash",h);v.put("state",0);long id=db.insertOrThrow("photos",null,v);if(src.delete()){db.execSQL("UPDATE photos SET state=1 WHERE id=?",new Object[]{id});done++;}else errors++;}finally{tmp.delete();}}
void export(File root,boolean remainder)throws Exception{long available=count(this);int n=remainder?(int)Math.min(available,99):100;if(remainder&&available>=100){status("Önce 100'lük paketleri ver; son kalanlar 100'den az olmalı.");return;}if(available<n||n==0){status("Kasada "+available+" fotoğraf var. 100'den azsa Son kalanları ver düğmesini kullan.");return;}if(!root.exists()&&!root.mkdirs())throw new IOException("Çıkış klasörü oluşturulamadı");File batch=new File(root,"Paket-"+System.currentTimeMillis());if(!batch.mkdir())throw new IOException("Paket oluşturulamadı");ArrayList<Long> ids=new ArrayList<>();ArrayList<File> targets=new ArrayList<>();ArrayList<File> originals=new ArrayList<>();boolean published=false;
try{try(Cursor c=db.rawQuery("SELECT id,name,stored,size,hash FROM photos WHERE state=1 ORDER BY id LIMIT "+n,null)){while(c.moveToNext()){if(cancel)throw new IOException("Durduruldu; fotoğraflar kasada kaldı");File src=new File(c.getString(2));File dst=new File(batch,String.format(Locale.ROOT,"%03d_",ids.size()+1)+c.getString(1));File tmp=new File(dst+".part");targets.add(tmp);copy(src,tmp);if(tmp.length()!=c.getLong(3)||!hash(tmp).equals(c.getString(4)))throw new IOException("Çıkış doğrulaması başarısız");ids.add(c.getLong(0));originals.add(src);status("Paket hazırlanıyor: "+ids.size()+"/"+n);}}if(ids.size()!=n)throw new IOException("Yeterli hazır fotoğraf yok");db.beginTransaction();try{for(int x=0;x<n;x++){File tmp=targets.get(x);File dst=new File(tmp.getPath().substring(0,tmp.getPath().length()-5));if(!tmp.renameTo(dst))throw new IOException("Paket kaydedilemedi");targets.set(x,dst);db.execSQL("UPDATE photos SET state=2,out=? WHERE id=?",new Object[]{dst.getAbsolutePath(),ids.get(x)});}db.setTransactionSuccessful();}finally{db.endTransaction();}published=true;for(int x=0;x<n;x++){released(targets.get(x));if(originals.get(x).delete())db.delete("photos","id=?",new String[]{""+ids.get(x)});}status(n+" fotoğraf verildi: "+batch.getAbsolutePath());android.media.MediaScannerConnection.scanFile(this,targets.stream().map(File::getAbsolutePath).toArray(String[]::new),null,null);
}catch(Exception e){if(!published){for(File f:targets)f.delete();batch.delete();}throw e;}}
}